VALUES (
  "亿铸科技", "—", "semiconductor", "design", false, "B 轮", "2026-08",
  $json${"name": "亿铸科技", "code": "—", "industry": "semiconductor", "seg": "design", "listed": false, "round": "B 轮", "last_funding": "2026-08", "data": {"seg": "design", "code": "—", "desc": "全球首家基于存算一体架构做高性能 AI 处理器的公司，ReRAM 阻变存储 + 全数字路线，精度最高 32bit，面向数据中心大算力。", "name": "亿铸科技", "tech": [{"date": "2020-06", "kind": "公司", "title": "苏州亿铸智能科技成立，落地苏州高新区"}, {"date": "2023", "kind": "技术", "title": "提出「超异构存算一体架构」，将存算阵列与通用计算单元深度异构融合"}, {"date": "2023", "kind": "产品动态", "title": "基于 ReRAM 的全数字存算一体 POC AI 处理器点亮，精度最高 32bit"}, {"date": "2026", "kind": "资质", "title": "入围工信部「算力强基揭榜行动」，以存算一体 AI 芯片助力算力基础设施升级"}, {"date": "2026-07", "kind": "技术", "title": "总裁徐芳在 2026 世界人工智能大会发布「通用存算一体三大定律」"}, {"date": "2026-07", "kind": "资本", "title": "宣布完成超 10 亿元新一轮融资（约 1.47 亿美元）"}, {"date": "2026-08", "kind": "资本", "title": "B 轮收官，成立以来累计融资突破 10 亿元"}], "round": "B 轮", "detail": "【定位】苏州亿铸智能科技有限公司（Yizhu Tech），2020-06-08 成立，总部苏州高新区塔园路，注册资本 2396.2449 万元，法定代表人熊大鹏（DAPENG XIONG）。公司定位为全球首家基于存算一体（Computing-in-Memory）架构研发高性能 AI 处理器的企业，主打 ReRAM 阻变存储 + 全数字化存算一体路线，面向数据中心、云计算、中心侧服务器等高端算力场景，并延伸至自动驾驶与边缘计算。国家级潜在独角兽、江苏省专精特新中小企业、创新型中小企业，已获授权发明专利 65 项、软件著作权 26 项，研发人员占比 83%。2026 年入围工信部「算力强基揭榜行动」。\n【技术路线：ReRAM + 全数字，与同业四条路都不同】存算一体目前分四条路线：知存科技走 NOR Flash 模拟、后摩智能与苹芯走 SRAM 数字、九天睿芯走 SRAM 模数混合，亿铸是唯一主攻「ReRAM + 全数字 + 数据中心级大算力」的。全数字的含义是计算全程在数字域完成，从根源消除模拟存算固有的噪声、电压衰减与温漂导致的精度损失，因此能把精度做到最高 32 bit——这是模拟方案无法达到的，模拟路线通常只能覆盖 4–8 bit 的语音唤醒与轻量推理。ReRAM（阻变存储器）靠电阻高低存储 0/1，非易失、单元面积小（4F² 级）、可三维堆叠，理论上密度比 SRAM 高一个量级、速度优于 NOR Flash，这是它敢做「数据中心级大算力」的底气——SRAM 存算的片上容量只有几十 MB，装不下大模型。\n【超异构架构】2023 年提出「超异构存算一体架构」：将存算阵列与通用计算单元深度异构融合，既承担矩阵乘这类 AI 核心算力，又保留通用计算能力，可独立完整运行 AI 业务。公司称基于 ReRAM 的 POC AI 处理器已点亮，第三方测试显示能效超过传统 AI 芯片 10 倍以上。公司同时提出「通用存算一体三大定律」（架构、生态、计算三个维度），试图为行业建立参考框架。\n【产品阶段：尚未量产，这是核心事实】当前产品形态为四类：① ReRAM 全数字存算一体 POC 验证芯片，全数字化路径、计算精度最高 32 bit，用于技术验证与客户原型测试；② 存算一体超异构 IP 核，配套编译器、驱动、算子库，可对外授权；③ 服务器板卡参考方案，适配标准服务器插槽的加速板卡；④ 原型方案与软件工具链。公司自述处于「POC 向工程样片、量产过渡」阶段。成立六年、累计融资 10 亿元仍未量产，反映大算力存算一体的工程化难度显著高于端侧路线。\n【团队】创始人、董事长兼 CEO 熊大鹏：西安电子科技大学计算机本科、华南理工大学自动控制硕士、美国德州大学奥斯汀分校半导体博士，另获应用数学与电气计算机工程两个硕士学位；曾任华中科技大学教师、ADC Telecommunications 资深技术经理与大产品线经理、美国 AI 芯片公司 Wave Computing 中国区总经理（带领产品线做到全球市占率第二），并任深创投中美基金投委会成员，中美芯片产业经验近 30 年。联合创始人、CTO Debajyoti Pal：中科院计算所 GPU 与 AI 芯片架构博士，30 余年全球 GPU 架构履历，历任高通多代 GPU 总负责人、华为海思 GPGPU 技术专家、Cadence 首席科学家，持有 90 余项海内外芯片专利。联合创始人、总裁徐芳：资深半导体产业运营专家，负责市场拓展与政企生态，2026 世界人工智能大会发布「通用存算一体三大定律」。核心团队来自高通、华为海思、NVIDIA、AMD，累计完成 20 余款 SoC 芯片量产。\n【资本】2026-07 宣布完成新一轮超 10 亿元（约 1.47 亿美元）融资，2026-08 B 轮收官，成立以来累计融资突破 10 亿元。B 轮投资方包括涌铧投资、中科英智投资、树院基金、大米创投、新微资本、众物投资、普超资本、上海纳米创投；老股东包括中科创星、联想之星、农银国际、Xction Capital。投资方结构为国资 + 产业资本 + 国际创投的组合，部分为产业客户直接出资。注意口径差异：有外媒称成立以来累计超 15 亿元，企查查口径为突破 10 亿元，差额可能来自 IP 授权收入或政府补助，引用时以 10 亿元为准。\n【风险】① 尚未量产：核心产品仍处 POC 向工程样片过渡，无规模化收入，工程化与良率未验证；② ReRAM 产业化风险：阻变存储的擦写寿命（endurance）与批次一致性至今缺少大规模商用验证，Intel Optane（PCM 路线）已退出，新型存储的量产难度被反复证明；③ 代工依赖：ReRAM 需要 foundry 提供专用工艺模块，全球可提供嵌入式 ReRAM 量产工艺的产线极少，国内能否稳定获得工艺产能比芯片设计本身更决定生死，此点公开信息完全未披露；④ 能效代价：数字域计算相比模拟存算面积与功耗更高，「全数字」换来了精度，也削弱了存算一体的能效优势，10 倍能效提升为公司自述口径、缺第三方独立复现；⑤ 竞争密集：国内知存、后摩、九天睿芯、苹芯、微纳核芯各有路线且部分已量产，国际上英伟达、AMD 通过近存与先进封装持续侵蚀该赛道价值；⑥ 估值与营收均未披露，缺少估值锚。\n【观察指标】工程样片流片与回片时点、首家量产客户与板卡交付量、IP 授权收入规模、ReRAM 代工合作方与工艺节点、32 bit 精度在真实大模型推理中的实测能效、B+ 轮或 Pre-IPO 融资节奏。", "listed": false, "funding": [{"inv": "涌铧投资、中科英智投资、树院基金、大米创投、新微资本、众物投资、普超资本、上海纳米创投；老股东中科创星、联想之星、农银国际、Xction Capital", "date": "2026-08", "round": "B 轮", "amount": "超10亿元（约1.47亿美元）"}, {"inv": "中科创星、联想之星、农银国际、Xction Capital 等；企查查显示累计 8 起融资事件、18 家私募机构参与", "date": "2020", "round": "A 轮及以前（多轮）", "amount": "未逐一披露"}], "industry": "semiconductor", "latestTech": "ReRAM 全数字存算一体 POC 芯片点亮（精度最高 32bit），能效超传统 AI 芯片 10 倍以上；处 POC 向工程样片过渡阶段", "lastFunding": "2026-08", "latestFunding": "2026-08 · B 轮（累计融资突破 10 亿元）"}}$json$::jsonb
);
